-- HC-MVP1-058 migration 0008: case_template + the 3 default case templates
-- (CASE-001/002/003/004). Forward-only; never edited in place once released
-- (R-DATA-002). Produces user_version = 8 (set by the migration runner).
--
-- The case_template table holds a JSON schema per template (sections[] with
-- fields[], field types, collapsible/hideable flags, showIf conditional
-- sections for female / child(<14), and single-choice pick lists that allow
-- free text). The three rows seeded here are the CASE-004 defaults: Chronic
-- detailed (is_default = 1), Acute quick, and Child. Their ids are the fixed
-- UUIDv7 constants exported from hc_storage::case_template so commands + tests
-- reference them deterministically (D3). Standard UUIDv7 id + audit columns
-- (R-DATA-005). Seed timestamps use the 1970 epoch like patient_sequence.
-- This file is schema DDL + fixed seed values; no external input (R-SEC-001).

CREATE TABLE case_template (
  id          TEXT PRIMARY KEY,               -- UUIDv7 (fixed for the 3 seeds)
  name        TEXT NOT NULL,                  -- 'Chronic detailed' | 'Acute quick' | 'Child'
  schema_json TEXT NOT NULL,                  -- JSON schema: sections[] -> fields[]
  is_default  INTEGER NOT NULL DEFAULT 0,     -- exactly one row has is_default = 1
  sort_order  INTEGER NOT NULL DEFAULT 0,
  created_at  TEXT NOT NULL,
  updated_at  TEXT NOT NULL,
  deleted_at  TEXT,
  created_by  TEXT,
  updated_by  TEXT,
  row_version INTEGER NOT NULL DEFAULT 0
);

-- At most one default template (partial unique index on is_default = 1).
CREATE UNIQUE INDEX ix_case_template_default ON case_template (is_default) WHERE is_default = 1;

INSERT INTO case_template (id, name, schema_json, is_default, sort_order, created_at, updated_at)
  VALUES ('01920000-0008-7000-8000-000000000001', 'Chronic detailed', '{"version":1,"sections":[{"key":"chief_complaints","title":"Chief complaints","collapsible":true,"hideable":true,"repeatable":true,"fields":[{"key":"location","label":"Location","type":"text"},{"key":"sensation","label":"Sensation","type":"long-text"},{"key":"agg","label":"Aggravation","type":"long-text"},{"key":"amel","label":"Amelioration","type":"long-text"},{"key":"concomitants","label":"Concomitants","type":"long-text"},{"key":"duration","label":"Duration","type":"text"},{"key":"onset","label":"Onset","type":"text"}]},{"key":"hpi","title":"History of present illness","collapsible":true,"hideable":true,"fields":[{"key":"narrative","label":"History of present illness","type":"long-text"}]},{"key":"past_history","title":"Past history","collapsible":true,"hideable":true,"fields":[{"key":"narrative","label":"Past history","type":"long-text"}]},{"key":"family_history","title":"Family history","collapsible":true,"hideable":true,"fields":[{"key":"narrative","label":"Family history","type":"long-text"}]},{"key":"personal_history","title":"Personal history","collapsible":true,"hideable":true,"fields":[{"key":"narrative","label":"Personal history","type":"long-text"}]},{"key":"physical_generals","title":"Physical generals","collapsible":true,"hideable":true,"fields":[{"key":"appetite","label":"Appetite","type":"text"},{"key":"thirst","label":"Thirst","type":"single-choice","allowFreeText":true,"options":["Thirstless","Small sips","Large quantities"]},{"key":"cravings","label":"Cravings","type":"long-text"},{"key":"aversions","label":"Aversions","type":"long-text"},{"key":"stool","label":"Stool","type":"text"},{"key":"urine","label":"Urine","type":"text"},{"key":"sweat","label":"Sweat","type":"text"},{"key":"sleep","label":"Sleep","type":"text"},{"key":"dreams","label":"Dreams","type":"long-text"},{"key":"thermal","label":"Thermal state","type":"single-choice","allowFreeText":true,"options":["Chilly","Hot","Ambithermal"]}]},{"key":"mental_generals","title":"Mental generals","collapsible":true,"hideable":true,"fields":[{"key":"narrative","label":"Mental generals","type":"long-text"}]},{"key":"menstrual_obstetric","title":"Menstrual / obstetric history","collapsible":true,"hideable":true,"showIf":{"sex":"female"},"fields":[{"key":"menses","label":"Menses","type":"long-text"},{"key":"obstetric","label":"Obstetric history","type":"long-text"},{"key":"leucorrhoea","label":"Leucorrhoea","type":"text"}]},{"key":"child_development","title":"Child development","collapsible":true,"hideable":true,"showIf":{"ageYearsLt":14},"fields":[{"key":"milestones","label":"Developmental milestones","type":"long-text"},{"key":"birth_history","label":"Birth history","type":"long-text"},{"key":"vaccination","label":"Vaccination","type":"text"},{"key":"schooling","label":"Schooling / behaviour","type":"long-text"}]},{"key":"examination","title":"Examination findings","collapsible":true,"hideable":true,"fields":[{"key":"bp","label":"BP","type":"text"},{"key":"pulse","label":"Pulse","type":"number"},{"key":"weight_kg","label":"Weight (kg)","type":"number"},{"key":"height_cm","label":"Height (cm)","type":"number"},{"key":"bmi","label":"BMI","type":"number","computed":"bmi(weight_kg,height_cm)"},{"key":"temp","label":"Temperature","type":"number"},{"key":"spo2","label":"SpO2","type":"number"},{"key":"pain_scale","label":"Pain scale","type":"scale0-10"}]},{"key":"investigations","title":"Investigations","collapsible":true,"hideable":true,"fields":[{"key":"narrative","label":"Investigations","type":"long-text"}]},{"key":"provisional_diagnosis","title":"Provisional diagnosis","collapsible":true,"hideable":true,"fields":[{"key":"dx","label":"Provisional diagnosis","type":"long-text"}]},{"key":"analysis","title":"Doctor''s analysis / notes","collapsible":true,"hideable":true,"fields":[{"key":"notes","label":"Analysis / notes","type":"long-text"}]}]}', 1, 0, '1970-01-01T00:00:00Z', '1970-01-01T00:00: